    public static function render(string $name, string $className = '', int $size = 20): string {
        $path = self::$icons[$name] ?? self::$icons['file'];
        return sprintf(
            '<svg class="lucide-icon %s" width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">%s</svg>',
            htmlspecialchars($className),
            $size,
            $size,
            $path
        );
